INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Endprodukt die einzige Ausgabe hier?', 2, '[{"text": "Nein", "correct": true, "because": "Prototypen und Berichte entstehen"}, {"text": "Ja", "correct": false, "because": "Mehrere Ausgaben pro Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausgabe hilft mir, Risiken zu dokumentieren?', 3, '[{"text": "Risikoberichte", "correct": true, "because": "Risiken festhalten"}, {"text": "Prototypen", "correct": false, "because": "Lösungen testen"}, {"text": "Endprodukt", "correct": false, "because": "Finale Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse entstehen in diesem Modell?', 5, '[{"text": "Prototypen", "correct": true, "because": "Testbare Lösungen"}, {"text": "Risikoberichte", "correct": true, "because": "Dokumentierte Analysen"}, {"text": "Unstrukturierte Notizen", "correct": false, "because": "Strukturierte Ausgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prototypen testen Ideen. b) Risikoberichte sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berichte essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Ausgaben?', 4, '[{"text": "Prototypen", "correct": false, "because": "Kern für Tests"}, {"text": "Risikoberichte", "correct": false, "because": "Risiken dokumentieren"}, {"text": "Unklare Ergebnisse", "correct": true, "because": "Strukturierte Ausgaben nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Prototypen hier unwichtig sind?', 2, '[{"text": "Nein", "correct": true, "because": "Zentral für Risikotests"}, {"text": "Ja", "correct": false, "because": "Wichtige Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausgabe wähle ich, um das finale Ziel zu erreichen?', 3, '[{"text": "Endprodukt", "correct": true, "because": "Letzte Zyklus-Ausgabe"}, {"text": "Risikoberichte", "correct": false, "because": "Dokumentation"}, {"text": "Prototypen", "correct": false, "because": "Zwischenergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse unterstützen die Entwicklung?', 5, '[{"text": "Prototypen", "correct": true, "because": "Ideen validieren"}, {"text": "Risikoberichte", "correct": true, "because": "Probleme identifizieren"}, {"text": "Zufällige Skizzen", "correct": false, "because": "Strukturierte Ausgaben nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Risikoberichte sind zentral. b) Endprodukt kommt sofort. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Endprodukt am Schluss"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Prototypen", "correct": false, "because": "Risiken testen"}, {"text": "Risikoberichte", "correct": false, "because": "Analyse sichern"}, {"text": "Unstrukturierte Daten", "correct": true, "because": "Klarheit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Endprodukt in jedem Zyklus fertig?', 2, '[{"text": "Nein", "correct": true, "because": "Nur am Ende"}, {"text": "Ja", "correct": false, "because": "Zyklische Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausgaben helfen bei der Risikoreduktion?', 4, '[{"text": "Risikoberichte", "correct": true, "because": "Probleme dokumentieren"}, {"text": "Prototypen", "correct": true, "because": "Lösungen ausprobieren"}, {"text": "Endprodukt", "correct": false, "because": "Finales Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Prototypen hier nutzlos sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wichtig für Tests"}, {"text": "Ja", "correct": false, "because": "Kern der Zyklen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in frühen Zyklen?', 3, '[{"text": "Prototypen", "correct": true, "because": "Risiken testen"}, {"text": "Endprodukt", "correct": false, "because": "Spätere Phase"}, {"text": "Unklare Berichte", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Risikoberichte analysieren Probleme. b) Prototypen sind endgültig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototypen vorläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Ausgaben?', 5, '[{"text": "Risikominimierung", "correct": true, "because": "Berichte und Prototypen"}, {"text": "Klarheit", "correct": true, "because": "Dokumentierte Schritte"}, {"text": "Unstrukturierte Ideen", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Prototypen", "correct": false, "because": "Risiken testen"}, {"text": "Risikoberichte", "correct": false, "because": "Analyse zentral"}, {"text": "Zufällige Ergebnisse", "correct": true, "because": "Struktur nötig"}]');
